const char *filepath = "output.txt";
mode_t permissions = 0644; // rw-r--r--

// Creates or truncates the file, opening it for writing
// Returns file descriptor (fd) or -1 on failure
int fd = creat(filepath, permissions);

if (fd == -1) {
    // EACCES: Missing write/search permission
    // EEXIST: Requires O_EXCL (but creat implicitly truncates)
    perror("creat failed");
    return EXIT_FAILURE;
}

// Write operation uses the returned descriptor
write(fd, "Hello", 5);

close(fd);
// File permissions are modified by umask
